import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { addCommentHandler } from "../handlers/addCommentHandler";
import type { ApiError } from "../runtime/client";
import type { AddPostCommentRequest } from "../types/AddPostCommentRequest";
import type { FeedPartition } from "../types/FeedPartition";

type Data = Awaited<ReturnType<typeof addCommentHandler>>;
type Vars = { postId: FeedPartition; req: AddPostCommentRequest };

export function useAddCommentHandler(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => addCommentHandler(vars.postId, vars.req),
    ...options,
  });
}
